// The plugin's tsconfig (generated by Orca) pins `typeRoots` to `.orca/types` and whitelists
// only Orca's own type packages, so `@types/node` is never in scope and the Node built-ins the
// tests need — a real shell for the marker tests, and the filesystem walk behind the emoji
// sweep — are declared here by hand.
declare module 'node:child_process' {
  /** Runs `command` through a shell and returns its stdout as text. */
  export function execSync(command: string, options: { encoding: string }): string
  /** Runs `argv` directly (no extra shell layer) and returns its stdout as text. */
  export function spawnSync(
    file: string,
    args: readonly string[],
    options: { encoding: string }
  ): { stdout: string; error?: Error }
}

declare module 'node:fs' {
  /** Whether `path` exists (any file type). */
  export function existsSync(path: string): boolean
  /** The names inside one directory (the plugin's `src/` for the emoji sweep). */
  export function readdirSync(path: string): string[]
  /** The whole file as text — `utf8` so code points survive the scan. */
  export function readFileSync(path: string, encoding: 'utf8'): string
}

declare module 'node:path' {
  /** Joins path segments with the platform separator. */
  export function join(...parts: string[]): string
  /** The directory part of one path, for walking up from the runner's cwd. */
  export function dirname(path: string): string
}

/** Where the test runner started, so the sweep finds `src/` from the repo root OR the plugin. */
declare const process: { cwd(): string }
